// Failure-mode detectors. Compose into your runtime.
import type { AgentStep } from '@/lib/schemas/agent-trace';

/** Detect infinite loops: same (tool, args) signature N+ times in window. */
export function detectInfiniteLoop(
  steps: AgentStep[],
  window = 6,
  threshold = 3,
): { detected: boolean; signature?: string } {
  const recent = steps.slice(-window).filter(s => s.kind === 'tool_call');
  const counts = new Map<string, number>();
  for (const s of recent) {
    const sig = `${s.tool?.name}:${JSON.stringify(s.tool?.args ?? {})}`;
    counts.set(sig, (counts.get(sig) ?? 0) + 1);
  }
  for (const [sig, n] of counts) {
    if (n >= threshold) return { detected: true, signature: sig };
  }
  return { detected: false };
}

/** Detect premature stop: final answer fails downstream validator. */
export function detectPrematureStop<T>(
  finalText: string,
  validator: (s: string) => { ok: boolean; reason?: string },
): { detected: boolean; reason?: string } {
  const v = validator(finalText);
  return v.ok ? { detected: false } : { detected: true, reason: v.reason };
}

/** Detect tool hallucination: tool name not in registry. */
export function detectToolHallucination(
  toolName: string,
  registry: ReadonlySet<string>,
): boolean {
  return !registry.has(toolName);
}

/** Parse-and-retry circuit breaker. */
export class ParseRetryCircuit {
  constructor(private readonly max = 2) {}
  private count = 0;
  attempt(): boolean {
    if (this.count >= this.max) return false;
    this.count++;
    return true;
  }
  reset(): void {
    this.count = 0;
  }
}
